public sealed class CanvasItem:INotifyPropertyChanged{private string n="",f="",k=CanvasContentKinds.Image,d=DecorationModes.None,m="";private double x,y,w=360,h=240,r,o=1;private bool flip,locked,hidden;private int z;private WidgetThemeKind theme=WidgetThemeKind.Auto;public Guid Id{get;set;}=Guid.NewGuid();public string DisplayName{get=>n;set=>Set(ref n,value??"");}public string StoredFileName{get=>f;set=>Set(ref f,value??"");}public string ContentKind{get=>k;set{var v=value??CanvasContentKinds.Image;if(k==v)return;k=v;if(v!=CanvasContentKinds.Clock){w=Math.Max(48,w);h=Math.Max(48,h);}Changed(nameof(ContentKind));Changed(nameof(KindLabel));}}[JsonPropertyName("mediaKind")]public string LegacyMediaKind{set=>ContentKind=value;}[JsonIgnore]public string MediaKind{get=>ContentKind;set=>ContentKind=value;}public string DecorationMode{get=>d;set=>Set(ref d,value??DecorationModes.None);}public WidgetThemeKind Theme{get=>theme;set=>Set(ref theme,Enum.IsDefined(value)?value:WidgetThemeKind.Auto);}public ClockOptions Clock{get;set;}=new();public NowPlayingOptions NowPlaying{get;set;}=new();public SystemMonitorOptions SystemMonitor{get;set;}=new();public string MonitorDevice{get=>m;set=>Set(ref m,value??"");}public double CenterX{get=>x;set=>Set(ref x,value);}public double CenterY{get=>y;set=>Set(ref y,value);}public double Width{get=>w;set=>Set(ref w,CanvasItemSizing.Normalize(value,k));}public double Height{get=>h;set=>Set(ref h,CanvasItemSizing.Normalize(value,k));}public double RotationDegrees{get=>r;set=>Set(ref r,Geometry.NormalizeDegrees(value));}public double Opacity{get=>o;set=>Set(ref o,Math.Clamp(value,.05,1));}public bool IsFlipped{get=>flip;set=>Set(ref flip,value);}public bool IsLocked{get=>locked;set=>Set(ref locked,value);}public int ZIndex{get=>z;set=>Set(ref z,value);}[JsonIgnore]public bool IsTemporarilyHidden{get=>hidden;set=>Set(ref hidden,value);}[JsonIgnore]public string KindLabel=>k switch{CanvasContentKinds.Gif=>"GIF",CanvasContentKinds.Clock=>"時計",Can