public readonly record struct DisplayArea(string DeviceName,double Left,double Top,double Width,double Height,bool IsPrimary){public double Right=>Left+Width;public double Bottom=>Top+Height;}
public static class Geometry{private const double Visible=64;public static double NormalizeDegrees(double v){var r=v%360;if(r>180)r-=360;else if(r<=-180)r+=360;return Math.Round(r,2);}public static void ClampToDisplays(CanvasItem i,IReadOnlyList<DisplayArea> ds){if(ds.Count==0)return;var d=ds.FirstOrDefault(v=>i.CenterX>=v.Left&&i.CenterX<=v.Right&&i.CenterY>=v.Top&&i.CenterY<=v.Bottom);if(string.IsNullOrWhiteSpace(d.DeviceName))d=ds.FirstOrDefault(v=>string.Equals(v.DeviceName,i.MonitorDevice,StringComparison.OrdinalIgnoreCase));if(string.IsNullOrWhiteSpace(d.DeviceName))d=ds.FirstOrDefault(v=>v.IsPrimary);if(string.IsNullOrWhiteSpace(d.DeviceName))d=ds[0];var a=i.RotationDegrees*Math.PI/180;var bw=i.Width*Math.Abs(Math.Cos(a))+i.Height*Math.Abs(Math.Sin(a));var bh=i.Width*Math.Abs(Math.Sin(a))+i.Height*Math.Abs(Math.Cos(a));i.CenterX=Math.Clamp(i.CenterX,d.Left-bw/2+Math.Min(Visible,bw),d.Right+bw/2-Math.Min(Visible,bw));i.CenterY=Math.Clamp(i.CenterY,d.Top-bh/2+Math.Min(Visible,bh),d.Bottom+bh/2-Math.Min(Visible,bh));i.MonitorDevice=d.DeviceName;}}
